31	  - [ ] `Application/SeatMapService.cs` (neu): Klasse `SeatMapService(AppDbContext db)`, Methode `GetSeatMapAsync(int eventId, CancellationToken ct = default)` liefert `SeatMap?`. Derselbe explizite Join wie `EventQueryService`/`EventDetailService` (`Domain/Room` hat keine Navigation zurück zu `Event`), plus ein Set der aktuell belegten `(RowLabel, ColumnNumber)`-Paare aus `BookingPositions` **gefiltert auf `CancelledAtUtc == null`** (AD-1/AD-2 — ein poliert stornierter Platz gilt als frei, unabhängig davon ob die Zeile aus dem Anfangsdatenbestand oder einer Buchung stammt):
32	    ```csharp
33	    using Microsoft.EntityFrameworkCore;
34	    using seed_a_backend.Api.Domain;
35	    using seed_a_backend.Api.Infrastructure;
36	
37	    namespace seed_a_backend.Api.Application;
38	
39	    /// <summary>
40	    /// Grid-Struktur kommt 1:1 aus Domain/Room (AD-8); Zellstatus wird aus BookingPosition
41	    /// abgeleitet (AD-1/AD-2) — ein Sitzplatz gilt als belegt, wenn eine nicht stornierte
42	    /// BookingPosition-Zeile (CancelledAtUtc IS NULL) mit passendem RowLabel/ColumnNumber
43	    /// existiert, unabhängig davon, ob sie aus dem Anfangsdatenbestand oder einer Buchung stammt.
44	    /// </summary>
45	    public class SeatMapService(AppDbContext db)
46	    {
47	        public async Task<SeatMap?> GetSeatMapAsync(int eventId, CancellationToken ct = default)
48	        {
49	            var room = await (
50	                from e in db.Events
51	                join r in db.Rooms on e.RoomId equals r.Id
52	                where e.Id == eventId
53	                select r
54	            ).SingleOrDefaultAsync(ct);
55	
56	            if (room is null)
57	            {
58	                return null;
59	            }
60	
61	            var occupiedRows = await db.BookingPositions
62	                .Where(bp => bp.EventId == eventId && bp.CancelledAtUtc == null)
63	                .Select(bp => new { bp.RowLabel, bp.ColumnNumber })
64	                .ToListAsync(ct);
65	            var occupied = occupiedRows.Select(o => (o.RowLabel, o.ColumnNumber)).ToHashSet();
66	
67	            var rows = room.RowLabels
68	                .Select(rowLabel => new SeatMapRow(
69	                    rowLabel,
70	                    Enumerable.Range(1, room.ColumnCount)
71	                        .Select(column => new SeatMapCell(column, Status(room, occupied, rowLabel, column)))
72	                        .ToList()))
73	                .ToList();
74	
75	            return new SeatMap(room.RowLabels, room.ColumnCount, room.AisleColumns.ToList(), rows);
76	        }
77	
78	        private static string Status(Room room, HashSet<(string RowLabel, int ColumnNumber)> occupied, string rowLabel, int column) =>
79	            room.AisleColumns.Contains(column) ? "aisle"
80	                : occupied.Contains((rowLabel, column)) ? "occupied"
81	                : "free";
82	    }
83	    ```
