145	    ```typescript
146	    import { Component, ElementRef, computed, effect, input, signal, viewChild } from '@angular/core';
147	
148	    import { SeatMap, SeatMapCell } from '../../../core/api/seat-map';
149	
150	    interface FocusTarget {
151	      rowIndex: number;
152	      columnIndex: number;
153	    }
154	
155	    const KEY_DELTAS: Record<string, { rowDelta: number; columnDelta: number }> = {
156	      ArrowUp: { rowDelta: -1, columnDelta: 0 },
157	      ArrowDown: { rowDelta: 1, columnDelta: 0 },
158	      ArrowLeft: { rowDelta: 0, columnDelta: -1 },
159	      ArrowRight: { rowDelta: 0, columnDelta: 1 }
160	    };
161	
162	    @Component({
163	      selector: 'app-seat-map',
164	      imports: [],
165	      templateUrl: './seat-map.html',
166	      styleUrl: './seat-map.scss'
167	    })
168	    export class SeatMapGrid {
169	      readonly seatMap = input.required<SeatMap>();
170	
171	      private readonly root = viewChild.required<ElementRef<HTMLElement>>('root');
172	
173	      private readonly focusTarget = signal<FocusTarget | null>(null);
174	
175	      private readonly firstFreeTarget = computed<FocusTarget | null>(() => {
176	        const rows = this.seatMap().rows;
177	        for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
178	          const columnIndex = rows[rowIndex].cells.findIndex(cell => cell.status === 'free');
179	          if (columnIndex !== -1) {
180	            return { rowIndex, columnIndex };
181	          }
182	        }
183	        return null;
184	      });
185	
186	      constructor() {
187	        effect(() => {
188	          const target = this.focusTarget();
189	          if (target === null) {
190	            return;
191	          }
192	          const selector = `[data-row-index="${target.rowIndex}"][data-column-index="${target.columnIndex}"]`;
193	          this.root().nativeElement.querySelector<HTMLButtonElement>(selector)?.focus();
194	        });
195	      }
196	
197	      isRovingTabTarget(rowIndex: number, columnIndex: number): boolean {
198	        const current = this.focusTarget() ?? this.firstFreeTarget();
199	        return current !== null && current.rowIndex === rowIndex && current.columnIndex === columnIndex;
200	      }
201	
202	      ariaLabel(rowLabel: string, cell: SeatMapCell): string {
203	        const statusText = cell.status === 'occupied' ? 'belegt' : 'frei';
204	        return `Reihe ${rowLabel}, Platz ${cell.columnNumber}, ${statusText}`;
205	      }
206	
207	      onFocus(rowIndex: number, columnIndex: number): void {
208	        this.focusTarget.set({ rowIndex, columnIndex });
209	      }
210	
211	      onKeydown(event: KeyboardEvent, rowIndex: number, columnIndex: number): void {
212	        const delta = KEY_DELTAS[event.key];
213	        if (!delta) {
214	          return;
215	        }
216	        event.preventDefault();
217	        const next = this.findNextFocusable(rowIndex, columnIndex, delta.rowDelta, delta.columnDelta);
218	        if (next) {
219	          this.focusTarget.set(next);
220	        }
221	      }
222	
223	      private findNextFocusable(rowIndex: number, columnIndex: number, rowDelta: number, columnDelta: number): FocusTarget | null {
224	        const rows = this.seatMap().rows;
225	        let r = rowIndex + rowDelta;
226	        let c = columnIndex + columnDelta;
227	        while (r >= 0 && r < rows.length && c >= 0 && c < rows[r].cells.length) {
228	          if (rows[r].cells[c].status === 'free') {
229	            return { rowIndex: r, columnIndex: c };
230	          }
231	          r += rowDelta;
232	          c += columnDelta;
233	        }
234	        return null;
235	      }
236	    }
237	    ```
