    ```
  - [ ] `core/api/events-api.service.ts`: Import `SeatMap` aus `./seat-map` ergänzen, neue Methode `getSeatMap(id: number): Observable<SeatMap> { return this.http.get<SeatMap>(\`/api/events/${id}/seatmap\`); }` — bleibt in `EventsApiService`, da der Sitzplan eine untergeordnete Ressource der Veranstaltung ist (analog zu `getEvent`), kein eigener `SeatMapApiService` nötig. Bestehende `getEvents()`/`getEvent()` unverändert.
  - [ ] `core/api/events-api.service.spec.ts`: neuen Test ergänzen — `getSeatMap(1)` aufrufen, `httpMock.expectOne('/api/events/1/seatmap')` (Methode `GET`), `req.flush(...)` mit einer Beispiel-`SeatMap` (2 Reihen, 4 Spalten, `aisleColumns: [3]`, gemischte Status), Ergebnis per `toEqual` prüfen. Bestehende fünf Tests unverändert lassen.

- [ ] Task 4: Frontend — `seat-map`-Grid-Komponente (ARIA-Grid, Farb+Icon-Codierung, Tastaturnavigation) (AC: #2, #3, #4, #5)
  - [ ] Neuer Ordner `features/booking/seat-map/`. Komponentenklasse heißt **`SeatMapGrid`**, nicht `SeatMap` — Namenskollision mit dem gleichnamigen Modell-Interface aus `core/api/seat-map.ts` vermeiden, exakt dieselbe Begründung/Muster wie `EventDetailPage` vs. `EventDetail` in Story 1.5 `[ANNAHME]`. Selector `app-seat-map`, `templateUrl: './seat-map.html'`, `styleUrl: './seat-map.scss'`.
  - [ ] `seat-map.ts` (neu):
    ```typescript
    import { Component, ElementRef, computed, effect, input, signal, viewChild } from '@angular/core';

    import { SeatMap, SeatMapCell } from '../../../core/api/seat-map';

    interface FocusTarget {
      rowIndex: number;
      columnIndex: number;
    }

    const KEY_DELTAS: Record<string, { rowDelta: number; columnDelta: number }> = {
      ArrowUp: { rowDelta: -1, columnDelta: 0 },
      ArrowDown: { rowDelta: 1, columnDelta: 0 },
      ArrowLeft: { rowDelta: 0, columnDelta: -1 },
      ArrowRight: { rowDelta: 0, columnDelta: 1 }
    };

    @Component({
      selector: 'app-seat-map',
      imports: [],
      templateUrl: './seat-map.html',
      styleUrl: './seat-map.scss'
    })
    export class SeatMapGrid {
      readonly seatMap = input.required<SeatMap>();

      private readonly root = viewChild.required<ElementRef<HTMLElement>>('root');

      private readonly focusTarget = signal<FocusTarget | null>(null);

      private readonly firstFreeTarget = computed<FocusTarget | null>(() => {
        const rows = this.seatMap().rows;
        for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
          const columnIndex = rows[rowIndex].cells.findIndex(cell => cell.status === 'free');
          if (columnIndex !== -1) {
            return { rowIndex, columnIndex };
          }
        }
        return null;
      });

      constructor() {
        effect(() => {
          const target = this.focusTarget();
          if (target === null) {
            return;
          }
          const selector = `[data-row-index="${target.rowIndex}"][data-column-index="${target.columnIndex}"]`;
          this.root().nativeElement.querySelector<HTMLButtonElement>(selector)?.focus();
        });
      }

      isRovingTabTarget(rowIndex: number, columnIndex: number): boolean {
        const current = this.focusTarget() ?? this.firstFreeTarget();
        return current !== null && current.rowIndex === rowIndex && current.columnIndex === columnIndex;
      }

      ariaLabel(rowLabel: string, cell: SeatMapCell): string {
        const statusText = cell.status === 'occupied' ? 'belegt' : 'frei';
        return `Reihe ${rowLabel}, Platz ${cell.columnNumber}, ${statusText}`;
      }

      onFocus(rowIndex: number, columnIndex: number): void {
        this.focusTarget.set({ rowIndex, columnIndex });
      }

      onKeydown(event: KeyboardEvent, rowIndex: number, columnIndex: number): void {
        const delta = KEY_DELTAS[event.key];
        if (!delta) {
          return;
        }
        event.preventDefault();
        const next = this.findNextFocusable(rowIndex, columnIndex, delta.rowDelta, delta.columnDelta);
        if (next) {
          this.focusTarget.set(next);
        }
      }

      private findNextFocusable(rowIndex: number, columnIndex: number, rowDelta: number, columnDelta: number): FocusTarget | null {
        const rows = this.seatMap().rows;
        let r = rowIndex + rowDelta;
        let c = columnIndex + columnDelta;
        while (r >= 0 && r < rows.length && c >= 0 && c < rows[r].cells.length) {
          if (rows[r].cells[c].status === 'free') {
            return { rowIndex: r, columnIndex: c };
          }
          r += rowDelta;
          c += columnDelta;
        }
        return null;
      }
    }
    ```
    `[ANNAHME]`: Pfeiltasten überspringen belegte/Gang-Zellen und springen zur nächsten freien Zelle in dieser Richtung (bis zum Rand, dann bleibt der Fokus stehen) — `EXPERIENCE.md` → Accessibility Floor spezifiziert nur "Pfeiltasten zur Navigation zwischen Zellen", kein exaktes Skip-Verhalten. Belegte Zellen werden als natives `disabled`-`<button>` gerendert (siehe Template) — dadurch sind sie automatisch aus der Tab-Reihenfolge und für `.focus()` nicht erreichbar, ohne zusätzliche `tabindex`-Logik. Gang-Positionen sind kein `<button>`, tragen kein `role="gridcell"` (siehe `EXPERIENCE.md`: "Gang-Positionen sind keine Grid-Zellen und werden nicht angekündigt") und brauchen daher ebenfalls keinen Fokus-Handler. Roving Tabindex nur unter den freien Zellen: die zuletzt fokussierte (oder beim ersten Rendern die erste freie Zelle in Lesereihenfolge) trägt `tabindex="0"`, alle anderen freien Zellen `tabindex="-1"`.
  - [ ] `seat-map.html` (neu):
    ```html
    <div class="seat-map__scroll">
      <div class="seat-map" role="grid" aria-label="Sitzplan" #root>
        @for (row of seatMap().rows; track row.rowLabel; let rowIndex = $index) {
          <div class="seat-map__row" role="row">
            @for (cell of row.cells; track cell.columnNumber; let columnIndex = $index) {
              @if (cell.status === 'aisle') {
                <div class="seat-cell seat-cell--aisle" aria-hidden="true"></div>
              } @else if (cell.status === 'occupied') {
                <button
                  type="button"
                  class="seat-cell seat-cell--occupied"
                  role="gridcell"
                  disabled
                  [attr.aria-label]="ariaLabel(row.rowLabel, cell)"
                >
                  <span class="seat-cell__icon seat-cell__icon--lock" aria-hidden="true"></span>
                  <span class="seat-cell__label">{{ row.rowLabel }}{{ cell.columnNumber }}</span>
                </button>
              } @else {
                <button
                  type="button"
                  class="seat-cell seat-cell--free"
                  role="gridcell"
                  [attr.aria-label]="ariaLabel(row.rowLabel, cell)"
                  [attr.tabindex]="isRovingTabTarget(rowIndex, columnIndex) ? 0 : -1"
                  [attr.data-row-index]="rowIndex"
                  [attr.data-column-index]="columnIndex"
                  (focus)="onFocus(rowIndex, columnIndex)"
                  (keydown)="onKeydown($event, rowIndex, columnIndex)"
                >
                  <span class="seat-cell__icon seat-cell__icon--seat" aria-hidden="true"></span>
                  <span class="seat-cell__label">{{ row.rowLabel }}{{ cell.columnNumber }}</span>
                </button>
              }
            }
          </div>
        }
      </div>
    </div>
    ```
    Sitzplatz-Code (`row.rowLabel` + `cell.columnNumber`, z. B. "B3") bleibt in jedem Zustand als Text sichtbar (`DESIGN.md` seat-cell), Icons sind `aria-hidden="true"` (rein dekorativ, die Semantik trägt `aria-label`). `data-row-index`/`data-column-index` dienen ausschließlich der programmatischen Fokussteuerung aus `seat-map.ts`, keine visuelle Bedeutung.
  - [ ] `seat-map.scss` (neu), `@use '../../../../breakpoints' as *;` (vier Ebenen von `src/` bis `features/booking/seat-map/`):
    ```scss
    @use '../../../../breakpoints' as *;

    .seat-map__scroll {
      overflow-x: auto;
