28	            RoomId = raum.Id,
29	            Titel = "Kammerkonzert Frühling",
30	            Beschreibung = "Ein intimes Konzert mit klassischen Stücken.",
31	            Zeitpunkt = new DateTime(2026, 9, 5, 19, 30, 0),
