51	        Assert.Equal(0, result.Altersfreigabe);
52	        Assert.Equal("Spielstätte Nord", result.Spielstaette);
53	        Assert.Equal("Kleiner Saal", result.Raum);
54	        Assert.Equal(new DateTime(2026, 9, 5, 19, 30, 0), result.Zeitpunkt);
55	        Assert.Collection(result.Preiskategorien,
56	            pc => { Assert.Equal("Kategorie A", pc.Name); Assert.Equal(32.00m, pc.Preis); },
57	            pc => { Assert.Equal("Kategorie B", pc.Name); Assert.Equal(22.00m, pc.Preis); });
58	    }
